svg.script:

const svg = document.querySelector('svg');
const snakeGroup = document.getElementById('snake');
const food = document.getElementById('food');
const scoreText = document.getElementById('score');
let snake = [{x: 10, y: 15}];
let foodPos = {x: 15, y: 15};
let foodType = 'fish-red';
let score = 0;
let gameInterval;

function drawSnake() {
  snakeGroup.innerHTML = '';
  snake.forEach((segment, index) => {
    const element = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    element.setAttribute('x', segment.x);
    element.setAttribute('y', segment.y);
    element.setAttribute('width', 1);
    element.setAttribute('height', 1);
    element.setAttribute('rx', 0.2);
    element.setAttribute('class', index === 0 ? 'snake-head' : 'snake-body');
    snakeGroup.appendChild(element);
  });
}

function getNextMove() {
  const head = snake[0];
  const dx = foodPos.x - head.x;
  const dy = foodPos.y - head.y;
  let direction = {x: 0, y: 0};

  if (Math.abs(dx) > Math.abs(dy)) {
    direction.x = dx > 0 ? 1 : -1;
  } else {
    direction.y = dy > 0 ? 1 : -1;
  }

  const nextHead = {x: head.x + direction.x, y: head.y + direction.y};
  if (snake.some(seg => seg.x === nextHead.x && seg.y === nextHead.y)) {
    direction = {x: 0, y: 0};
    if (Math.abs(dx) <= Math.abs(dy)) {
      direction.x = dx > 0 ? 1 : -1;
    } else {
      direction.y = dy > 0 ? 1 : -1;
    }
  }

  return direction;
}

function spawnFood() {
  const foodTypes = ['fish-red', 'fish-yellow', 'fish-blue', 'gold'];
  const probabilities = [0.3, 0.3, 0.3, 0.1];
  let rand = Math.random();
  let cumulative = 0;
  let selectedType = 'fish-red';
  for (let i = 0; i < probabilities.length; i++) {
    cumulative += probabilities[i];
    if (rand < cumulative) {
      selectedType = foodTypes[i];
      break;
    }
  }

  foodPos = {x: Math.floor(Math.random() * 85.4), y: Math.floor(Math.random() * 30)};
  while (snake.some(seg => seg.x === foodPos.x && seg.y === foodPos.y)) {
    foodPos = {x: Math.floor(Math.random() * 85.4), y: Math.floor(Math.random() * 30)};
  }
  foodType = selectedType;
  food.setAttribute('x', foodPos.x);
  food.setAttribute('y', foodPos.y + 0.5);
  food.setAttribute('class', foodType);
  food.textContent = foodType === 'gold' ? '💰' : '🐟';
}

function moveSnake() {
  const direction = getNextMove();
  const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};

  if (head.x < 0 || head.x >= 85.4 || head.y < 0 || head.y >= 30) {
    clearInterval(gameInterval);
    alert('Game Over! Your score: ' + score);
    return;
  }

  snake.unshift(head);
  if (Math.abs(head.x - foodPos.x) < 0.5 && Math.abs(head.y - foodPos.y) < 0.5) {
    score += foodType === 'gold' ? 5 : 1;
    scoreText.textContent = 'Score: ' + score;
    spawnFood();
  } else {
    snake.pop();
  }
  drawSnake();
}

spawnFood();
gameInterval = setInterval(moveSnake, 150);
drawSnake();
